/* Typed API client: the paths and bodies come from the OpenAPI contract (api-schema.ts, generated by
   `npm run gen:api` from openapi.json, itself exported from the server's Pydantic models).
   Calls go through apiFetch (ID token, retry on 401); unwrap() returns the body of a success or throws an ApiError. */
import createClient, { type Client } from "openapi-fetch";
import type { InjectionKey } from "vue";
import type { ApiFetch } from "./api";
import type { components, paths } from "./api-schema";

export type ApiClient = Client<paths>;
/** Bodies of the API (Pydantic models), e.g. Schemas["CloudDbStatus"]. */
export type Schemas = components["schemas"];

/** A refused or failed call, with the message to show. status 0: the server could not be reached. */
export class ApiError extends Error {
  constructor(
    readonly status: number,
    readonly code: string | null,
    message: string,
  ) {
    super(message);
    this.name = "ApiError";
  }
}

export const NETWORK_MESSAGE = "Serveur injoignable : vérifiez la connexion réseau.";

function defaultMessage(status: number): string {
  if (status === 401) {
    return "Session refusée par le serveur : reconnectez-vous.";
  }
  if (status === 403) {
    return "Action non autorisée pour votre rôle.";
  }
  if (status === 404) {
    return "Élément introuvable sur le serveur.";
  }
  return `Le serveur ne répond pas correctement (erreur ${status}).`;
}

/** Field names of a FastAPI validation error (422): [{loc: ["body", "field"], msg}]. */
function invalidFields(detail: unknown[]): string {
  const names = detail.map((d) => {
    const loc = (d as { loc?: unknown }).loc;
    return Array.isArray(loc) ? String(loc[loc.length - 1]) : "";
  });
  return [...new Set(names.filter(Boolean))].join(", ");
}

/**
 * The API's error bodies: {status: "error", message, code?} (api/responses.py error()), FastAPI's {detail: string}
 * and {detail: [...]} (validation), or anything else (proxy page, empty body).
 */
export function errorFromBody(status: number, body: unknown): ApiError {
  if (body && typeof body === "object") {
    const { message, code, detail } = body as { message?: unknown; code?: unknown; detail?: unknown };
    const codeText = typeof code === "string" ? code : null;
    if (typeof message === "string" && message) {
      return new ApiError(status, codeText, message);
    }
    if (typeof detail === "string" && detail) {
      return new ApiError(status, codeText, detail);
    }
    if (Array.isArray(detail)) {
      const fields = invalidFields(detail);
      return new ApiError(status, "validation", `Données refusées par le serveur${fields ? ` (${fields})` : ""}.`);
    }
  }
  return new ApiError(status, null, defaultMessage(status));
}

export function createApiClient(api: ApiFetch, baseUrl: string = location.origin): ApiClient {
  return createClient<paths>({
    baseUrl,
    // openapi-fetch builds a Request; apiFetch adds the token to its headers
    fetch: async (request: Request) => {
      const hasBody = request.method !== "GET" && request.method !== "HEAD";
      return api(request.url, { method: request.method, headers: request.headers, body: hasBody ? await request.text() : undefined });
    },
  });
}

/** The body of a success; throws an ApiError for a refusal, a server error or a network failure. */
export async function unwrap<T>(call: Promise<{ data?: T; error?: unknown; response: Response }>): Promise<T> {
  let result: { data?: T; error?: unknown; response: Response };
  try {
    result = await call;
  } catch (e) {
    if (e instanceof TypeError) {
      throw new ApiError(0, "network", NETWORK_MESSAGE);
    } // fetch rejects offline
    throw new ApiError(0, null, "Réponse illisible du serveur."); // e.g. a success body that is not JSON
  }
  if (result.response.ok) {
    return result.data as T;
  }
  throw errorFromBody(result.response.status, result.error);
}

/** Message of any error caught around an API call. */
export function errorText(e: unknown): string {
  return e instanceof ApiError ? e.message : "Erreur inattendue.";
}

/** Provided by main.ts; the pages' tests provide one built on a fake ApiFetch. */
export const CLIENT_KEY: InjectionKey<ApiClient> = Symbol("client");
